import { NextResponse } from "next/server";
import { z } from "zod";
import { prisma } from "@/lib/db";
import { existsObject } from "@/lib/s3";

const Body = z.object({ pdfId: z.string().min(1) });

export async function POST(req: Request) {
  const json = await req.json().catch(() => null);
  const parsed = Body.safeParse(json);
  if (!parsed.success) {
    return NextResponse.json({ error: "Invalid payload" }, { status: 400 });
  }

  const pdf = await prisma.pdf.findUnique({ where: { id: parsed.data.pdfId } });
  if (!pdf) return NextResponse.json({ error: "Not found" }, { status: 404 });

  const ok = await existsObject(pdf.storageKey);
  if (!ok) {
    // optional: delete the DB row so it never shows up broken
    await prisma.pdf.delete({ where: { id: pdf.id } }).catch(() => {});
    return NextResponse.json(
      { error: "Upload not found in S3 (NoSuchKey). Removed DB row." },
      { status: 409 }
    );
  }

  return NextResponse.json({ pdfId: pdf.id, uploadUrl });

}
